def transform(grid):
    g = np.array(grid)
    h, w = g.shape
    bg = 0
    out = np.full((5 * h, 5 * w), bg, dtype=int)
    emit(out, "Allocate a 5x5 board of input-sized tiles, all background.")
    # The input's non-zero colour (5 in every pair).
    vals = [v for v in np.unique(g) if v != bg]
    col = vals[0] if vals else 5
    cells = [(r, c) for r in range(h) for c in range(w) if g[r, c] != bg]
    # Core: each coloured input cell becomes a full tile.
    for r, c in cells:
        out[(r + 1) * h:(r + 2) * h, (c + 1) * w:(c + 2) * w] = col
    emit(out, "Core: each coloured input cell becomes a full tile in the middle 3x3 tile block.")
    # Ring: each full tile on the core's edge gets an input copy just outside it.
    for r, c in cells:
        dirs = []
        if r == 0: dirs.append((-1, 0))
        if r == h - 1: dirs.append((1, 0))
        if c == 0: dirs.append((0, -1))
        if c == w - 1: dirs.append((0, 1))
        for dr, dc in dirs:
            tr, tc = r + 1 + dr, c + 1 + dc
            out[tr * h:(tr + 1) * h, tc * w:(tc + 1) * w] = g
        if dirs:
            emit(out, f"Full tile from input cell ({r},{c}) sits on the core edge: stamp the input pattern in the outward tile(s).")
    emit(out, "Final output.")
    return out
